WITH base AS (SELECT id, name, email, country, signup_date, is_active, credit_limit, INITCAP(TRIM(city)) AS city_title, ADD_MONTHS(signup_date, 1) AS signup_date_plus_months FROM customers WHERE signup_date > DATE '2023-08-09') SELECT country, ROUND(SUM(credit_limit) / NULLIF(COUNT(CASE WHEN country = 'US' THEN 1 END), 0), 2) AS credit_limit_per_us, APPROX_PERCENTILE(credit_limit, ARRAY(0.25, 0.5, 0.75)) AS credit_limit_quartiles, COUNT(*) AS event_count, SUM(CASE WHEN country = 'US' THEN credit_limit ELSE 0 END) AS us_credit_limit, GROUPING(country) AS grouping_level FROM base GROUP BY CUBE (country);
